CREATE TABLE IF NOT EXISTS public.grammar_curriculum_n3_rebuild (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day_number integer NOT NULL CHECK (day_number BETWEEN 1 AND 36), pattern_order integer NOT NULL, pattern text NOT NULL, source_book text NOT NULL DEFAULT 'ALL - BUNPO N3-2.pdf', source_page integer, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(day_number, pattern_order));
